import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

// The android/ directory is generated by `cap add android` + `cap sync` and is
// gitignored, so the in-app updater's native plugin must be (re)written by a
// configure script — same pattern as the deeplink/icons/permissions scripts.
const PLUGIN_PATH = 'android/app/src/main/java/chat/veyra/mobile/AppUpdatePlugin.java';
const ACTIVITY_PATH = 'android/app/src/main/java/chat/veyra/mobile/MainActivity.java';

const PLUGIN_SOURCE = `package chat.veyra.mobile;

import android.content.Intent;
import android.net.Uri;
import androidx.core.content.FileProvider;
import com.getcapacitor.JSObject;
import com.getcapacitor.Plugin;
import com.getcapacitor.PluginCall;
import com.getcapacitor.PluginMethod;
import com.getcapacitor.annotation.CapacitorPlugin;
import java.io.File;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * In-app APK self-update: downloads the release APK with progress events,
 * then hands it to the system package installer via FileProvider.
 */
@CapacitorPlugin(name = "AppUpdate")
public class AppUpdatePlugin extends Plugin {
    private static final String EVENT_PROGRESS = "downloadProgress";
    private static final long PROGRESS_INTERVAL_MS = 200;

    private final AtomicBoolean cancelled = new AtomicBoolean(false);

    @PluginMethod
    public void downloadAndInstall(PluginCall call) {
        final String url = call.getString("url");
        if (url == null || url.isEmpty()) {
            call.reject("Missing download url.");
            return;
        }
        cancelled.set(false);
        final File target = new File(getContext().getCacheDir(), "veyra-update.apk");
        Thread worker = new Thread(() -> {
            try {
                HttpURLConnection conn = (HttpURLConnection) new URL(url).openConnection();
                conn.setInstanceFollowRedirects(true);
                conn.setConnectTimeout(15000);
                conn.setReadTimeout(30000);
                conn.setRequestProperty("User-Agent", "Veyra-Updater");
                conn.connect();
                int code = conn.getResponseCode();
                if (code < 200 || code >= 300) {
                    throw new Exception("Download failed (HTTP " + code + ")");
                }
                long total = conn.getContentLengthLong();
                long received = 0;
                long lastEmit = 0;
                try (InputStream in = conn.getInputStream(); FileOutputStream out = new FileOutputStream(target)) {
                    byte[] buffer = new byte[64 * 1024];
                    int read;
                    while ((read = in.read(buffer)) != -1) {
                        if (cancelled.get()) {
                            target.delete();
                            JSObject ev = new JSObject();
                            notifyListeners("downloadCancelled", ev);
                            return;
                        }
                        out.write(buffer, 0, read);
                        received += read;
                        long now = System.currentTimeMillis();
                        if (now - lastEmit >= PROGRESS_INTERVAL_MS) {
                            lastEmit = now;
                            JSObject ev = new JSObject();
                            ev.put("received", received);
                            ev.put("total", total);
                            notifyListeners(EVENT_PROGRESS, ev);
                        }
                    }
                }
                JSObject ready = new JSObject();
                ready.put("path", target.getAbsolutePath());
                ready.put("size", target.length());
                notifyListeners("downloadReady", ready);
                android.app.Activity activity = getActivity();
                if (activity != null) {
                    activity.runOnUiThread(() -> install(target));
                } else {
                    JSObject ev = new JSObject();
                    ev.put("error", "App is not in the foreground.");
                    notifyListeners("installFailed", ev);
                }
            } catch (Exception error) {
                target.delete();
                JSObject ev = new JSObject();
                ev.put("error", error.getMessage() == null ? "Download failed" : error.getMessage());
                notifyListeners("downloadFailed", ev);
            }
        }, "veyra-apk-download");
        worker.start();
        call.resolve();
    }

    @PluginMethod
    public void cancel(PluginCall call) {
        cancelled.set(true);
        call.resolve();
    }

    private void install(File apk) {
        try {
            String authority = getContext().getPackageName() + ".fileprovider";
            Uri uri = FileProvider.getUriForFile(getContext(), authority, apk);
            Intent intent = new Intent(Intent.ACTION_VIEW);
            intent.setDataAndType(uri, "application/vnd.android.package-archive");
            intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_ACTIVITY_NEW_TASK);
            getContext().startActivity(intent);
        } catch (Exception error) {
            JSObject ev = new JSObject();
            ev.put("error", error.getMessage() == null ? "Could not open installer" : error.getMessage());
            notifyListeners("installFailed", ev);
        }
    }
}
`;

const ACTIVITY_SOURCE = `package chat.veyra.mobile;

import android.os.Bundle;
import com.getcapacitor.BridgeActivity;

public class MainActivity extends BridgeActivity {
    @Override
    public void onCreate(Bundle savedInstanceState) {
        registerPlugin(AppUpdatePlugin.class);
        super.onCreate(savedInstanceState);
    }
}
`;

await mkdir(dirname(PLUGIN_PATH), { recursive: true });
const existingPlugin = await readFile(PLUGIN_PATH, 'utf8').catch(() => null);
if (existingPlugin !== PLUGIN_SOURCE) {
  await writeFile(PLUGIN_PATH, PLUGIN_SOURCE);
  console.log('Wrote AppUpdatePlugin.java.');
} else {
  console.log('AppUpdatePlugin.java already up to date.');
}

const activity = await readFile(ACTIVITY_PATH, 'utf8').catch(() => null);
if (activity === null) {
  await mkdir(dirname(ACTIVITY_PATH), { recursive: true });
  await writeFile(ACTIVITY_PATH, ACTIVITY_SOURCE);
  console.log('Wrote MainActivity.java.');
} else if (!activity.includes('AppUpdatePlugin')) {
  await writeFile(ACTIVITY_PATH, ACTIVITY_SOURCE);
  console.log('Updated MainActivity.java to register AppUpdatePlugin.');
} else {
  console.log('MainActivity.java already registers AppUpdatePlugin.');
}
